// 继承在生成期拍平（§16.7.2）：ancestors 根在前；attrs = 本体声明 ∪
// 祖先链并集（G-6 展开批，按 attr id 升序无重复——子重声明在解析层拒绝）。
struct EntityMeta {
    const char* name;
    const char* parent;
    const char* const* ancestors;
    size_t ancestorCount;
    const AttrId* attrs;
    size_t attrCount;
    const char* desc;
};
